// 手動開單「銷貨單」PDF 功能
//
// 說明：這個 App 是純前端（部署在 GitHub Pages），沒有後端伺服器可以產生真正的 .pdf 檔案，
// 所以採用「開一個排版好的銷貨單頁面 → 呼叫瀏覽器列印 → 使用者在列印視窗選『另存為 PDF』」
// 這個做法，不用額外加大包的 PDF 套件（中文字型在那些套件裡常常要另外處理，容易出現方框亂碼）。
// 操作上跟真的下載 PDF只差一步：列印視窗出現後，印表機選單選「另存為 PDF」，按儲存就好。
import { COMPANY_INFO } from './config';
import { fmt } from './format';

export function printInvoice(order) {
  const win = window.open('', '_blank', 'width=900,height=1000');
  if (!win) {
    alert('瀏覽器擋住了彈出視窗，請允許這個網站開啟彈出視窗後再試一次（通常在網址列右邊會有一個被擋住的圖示）。');
    return;
  }

  const taxType = order.taxType || 'taxed';
  const subtotal = order.subtotal || 0;
  const untaxed  = taxType === 'taxed' ? Math.round(subtotal / 1.05) : subtotal;
  const taxAmt   = taxType === 'taxed' ? Math.round(subtotal - subtotal / 1.05) : Math.round(subtotal * 0.05);
  const total    = taxType === 'taxed' ? subtotal : Math.round(subtotal * 1.05);

  const buyerTitle = order.dealerTitle || order.customer || '';
  const buyerTaxId = order.dealerTaxId || '';

  const rows = (order.items || []).map(item => `
    <tr>
      <td class="mono">${item.code || ''}</td>
      <td>${item.name || ''}</td>
      <td class="num">${item.qty || 0}</td>
      <td class="num">${fmt.currency(item.price || 0)}</td>
      <td class="num">${fmt.currency((item.price || 0) * (item.qty || 0))}</td>
    </tr>
  `).join('');

  const html = `<!DOCTYPE html>
<html lang="zh-Hant">
<head>
<meta charset="UTF-8">
<title>銷貨單 ${order.id || ''}</title>
<style>
  * { box-sizing: border-box; }
  body { font-family: "Microsoft JhengHei","PingFang TC","Heiti TC",sans-serif; color:#111; padding:40px; max-width:800px; margin:0 auto; }
  h1 { text-align:center; letter-spacing:8px; font-size:28px; margin:0 0 24px; }
  .top { display:flex; justify-content:space-between; margin-bottom:20px; font-size:14px; }
  .box { border:1px solid #333; border-radius:4px; padding:12px 16px; font-size:14px; line-height:1.8; margin-bottom:16px; }
  .box-title { font-weight:700; margin-bottom:4px; }
  table { width:100%; border-collapse:collapse; margin-top:10px; font-size:14px; }
  th, td { border:1px solid #333; padding:8px 10px; }
  th { background:#f0f0f0; }
  .num { text-align:right; }
  .mono { font-family:monospace; }
  .totals { margin-top:10px; width:300px; margin-left:auto; font-size:14px; }
  .totals div { display:flex; justify-content:space-between; padding:4px 0; }
  .totals .grand { font-size:18px; font-weight:700; border-top:2px solid #333; margin-top:6px; padding-top:8px; }
  .note { margin-top:20px; font-size:13px; color:#555; }
  .footer { margin-top:50px; display:flex; justify-content:space-between; font-size:13px; }
  .footer div { width:45%; border-top:1px solid #999; padding-top:6px; text-align:center; }
  @media print { body { padding:0; } }
</style>
</head>
<body>
  <h1>銷貨單</h1>
  <div class="top">
    <div>單號：${order.id || ''}</div>
    <div>日期：${order.date || ''}</div>
  </div>

  <div class="box">
    <div class="box-title">賣方</div>
    公司名稱：${COMPANY_INFO.name}<br/>
    統一編號：${COMPANY_INFO.taxId}<br/>
    地址：${COMPANY_INFO.address}<br/>
    電話：${COMPANY_INFO.phone}
  </div>

  <div class="box">
    <div class="box-title">買方（請款對象）</div>
    抬頭：${buyerTitle || '（未填）'}<br/>
    統一編號：${buyerTaxId || '（未填）'}<br/>
    客戶：${order.customer || ''}
  </div>

  <table>
    <thead>
      <tr><th>代號</th><th>品名</th><th class="num">數量</th><th class="num">單價</th><th class="num">小計</th></tr>
    </thead>
    <tbody>
      ${rows}
    </tbody>
  </table>

  <div class="totals">
    <div><span>未稅金額</span><span>${fmt.currency(untaxed)}</span></div>
    <div><span>營業稅（5%）</span><span>${fmt.currency(taxAmt)}</span></div>
    <div class="grand"><span>應付總額</span><span>${fmt.currency(total)}</span></div>
  </div>

  ${order.note ? `<div class="note">備註：${order.note}</div>` : ''}

  <div class="footer">
    <div>賣方簽章</div>
    <div>買方簽收</div>
  </div>

  <script>
    window.onload = function() { window.print(); };
  </script>
</body>
</html>`;

  win.document.open();
  win.document.write(html);
  win.document.close();
}
